package com.jesuscasta.pong3d;

import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.graphics.Color;
import android.content.res.Configuration;
import android.text.InputType;
import android.view.View;
import android.widget.*;
import androidx.appcompat.app.AppCompatActivity;
import org.json.*;
import okhttp3.*;
import java.util.concurrent.TimeUnit;

public class MainActivity extends AppCompatActivity {
 private final NativeGame game=new NativeGame();private PongSurface surface;private TextView status,score,profile;private EditText endpoint,name,password;private Button search,play,reset;private WebSocket socket;private String token,base;private boolean ready,queued;private long generation;private final Handler ui=new Handler(Looper.getMainLooper());private final OkHttpClient http=new OkHttpClient.Builder().callTimeout(15,TimeUnit.SECONDS).pingInterval(15,TimeUnit.SECONDS).build();
 private final Runnable pulse=new Runnable(){public void run(){synchronized(game){score.setText("TÚ  "+game.mine+"   —   "+game.theirs+"  "+(game.online?"RIVAL":"CPU"));if(game.online&&game.playing)send("move",game.target);if(game.winner!=-1&&!game.playing)status.setText(game.winner==0?"Victoria · juega otra partida":"Derrota · juega otra partida");play.setEnabled(!game.online);reset.setEnabled(!game.online);}ui.postDelayed(this,50);}};
 @Override public void onCreate(Bundle saved){super.onCreate(saved);boolean dark=(getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES;int bg=Color.parseColor(dark?"#141218":"#F8F7FF");LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(20,20,20,20);root.setBackgroundColor(bg);setContentView(root);
  TextView title=new TextView(this);title.setText("3DPong · Liga");title.setTextSize(28);root.addView(title);profile=new TextView(this);profile.setText("Partidas rápidas y clasificación por nivel");root.addView(profile);
  endpoint=field(root,"Servidor HTTPS",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);endpoint.setText(getPreferences(0).getString("endpoint",""));name=field(root,"Jugador (3–20 caracteres)",InputType.TYPE_CLASS_TEXT);password=field(root,"Contraseña (mín. 10 caracteres)",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);
  LinearLayout auth=new LinearLayout(this);root.addView(auth);button(auth,"Entrar",()->account(false));button(auth,"Crear cuenta",()->account(true));button(auth,"Salir",()->logout());
  LinearLayout online=new LinearLayout(this);root.addView(online);search=button(online,"Buscar rival",()->{if(!ready){status.setText("Primero inicia sesión");return;}if(queued){send("cancel",null);}else send("queue",null);});button(online,"Ranking",this::ranking);
  status=new TextView(this);status.setText("Arrastra para mover la pala");root.addView(status);score=new TextView(this);score.setTextSize(22);score.setGravity(17);root.addView(score);surface=new PongSurface(this,game);root.addView(surface,new LinearLayout.LayoutParams(-1,0,1));LinearLayout controls=new LinearLayout(this);root.addView(controls);play=button(controls,"Jugar / pausa",()->{synchronized(game){if(game.winner!=-1)game.reset();game.playing=!game.playing;}});reset=button(controls,"Reiniciar",()->{synchronized(game){game.reset();}});Spinner difficulty=new Spinner(this);difficulty.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Relax","Clásica","Intensa"}));difficulty.setSelection(1);difficulty.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> a,View v,int pos,long id){synchronized(game){game.difficulty=new float[]{2.5f,4,6}[pos];}}public void onNothingSelected(AdapterView<?> a){}});controls.addView(difficulty);ui.post(pulse);
 }
 private EditText field(LinearLayout root,String hint,int type){EditText v=new EditText(this);v.setSingleLine();v.setHint(hint);v.setInputType(type);root.addView(v);return v;}
 private Button button(LinearLayout root,String label,Runnable action){Button b=new Button(this);b.setText(label);b.setTextSize(12);root.addView(b,new LinearLayout.LayoutParams(0,-2,1));b.setOnClickListener(v->action.run());return b;}
 private boolean configure(){String input=endpoint.getText().toString().trim().replaceAll("/+$","");HttpUrl url=HttpUrl.parse(input);if(url==null||!url.isHttps()||!url.username().isEmpty()||!url.password().isEmpty()||!url.encodedPath().equals("/")||url.query()!=null||url.fragment()!=null){status.setText("Introduce la dirección HTTPS del servidor, sin rutas ni credenciales");return false;}base=input;getPreferences(0).edit().putString("endpoint",base).apply();return true;}
 private void request(String path,JSONObject body,String auth,java.util.function.Consumer<String> success){Request.Builder builder=new Request.Builder().url(base+path);if(auth!=null)builder.header("Authorization","Bearer "+auth);if(body!=null)builder.post(RequestBody.create(body.toString(),MediaType.get("application/json")));http.newCall(builder.build()).enqueue(new Callback(){public void onFailure(Call c,java.io.IOException e){ui.post(()->status.setText("No se pudo conectar"));}public void onResponse(Call c,Response r){try(Response response=r){String text=response.body().string();ui.post(()->{if(response.isSuccessful())success.accept(text);else{try{status.setText(new JSONObject(text).optString("error","Error del servidor"));}catch(Exception e){status.setText("Error del servidor");}}});}catch(Exception e){ui.post(()->status.setText("Respuesta no válida"));}}});}
 private void account(boolean register){synchronized(game){if(game.online){status.setText("Termina la partida antes de cambiar de cuenta");return;}}if(!configure())return;try{JSONObject body=new JSONObject().put("name",name.getText().toString()).put("password",password.getText().toString());request(register?"/api/register":"/api/login",body,null,text->{try{JSONObject data=new JSONObject(text);token=data.getString("token");password.setText("");showProfile(data.getJSONObject("user"));connect();}catch(Exception e){status.setText("Respuesta no válida");}});}catch(Exception e){status.setText("Revisa los datos");}}
 private void showProfile(JSONObject u){profile.setText(u.optString("name")+" · "+u.optInt("rating")+" Elo · "+u.optInt("wins")+" victorias");}
 private void connect(){long id=++generation;if(socket!=null)socket.close(1000,"Reconnect");ready=false;socket=http.newWebSocket(new Request.Builder().url(base.replaceFirst("https:","wss:")+"/socket").build(),new WebSocketListener(){public void onOpen(WebSocket ws,Response r){try{ws.send(new JSONObject().put("type","auth").put("token",token).toString());}catch(Exception ignored){}}public void onMessage(WebSocket ws,String text){ui.post(()->{if(id==generation)message(text);});}public void onFailure(WebSocket ws,Throwable t,Response r){ui.post(()->{if(id==generation)disconnected();});}public void onClosed(WebSocket ws,int code,String reason){ui.post(()->{if(id==generation)disconnected();});}});}
 private void disconnected(){ready=false;queued=false;search.setText("Buscar rival");synchronized(game){game.online=false;game.playing=false;}status.setText("Desconectado. Inicia sesión para reconectar.");}
 private void message(String text){try{JSONObject m=new JSONObject(text);String type=m.getString("type");synchronized(game){switch(type){case "ready":ready=true;showProfile(m.getJSONObject("user"));status.setText("Conectado");break;case "queued":queued=true;search.setText("Cancelar");status.setText("Buscando rival de nivel similar…");break;case "cancelled":queued=false;search.setText("Buscar rival");status.setText("Búsqueda cancelada");break;case "matched":queued=false;search.setText("Buscar rival");game.reset();game.online=true;status.setText("Contra "+m.getJSONObject("opponent").getString("name")+" · empieza en 3 segundos");break;case "state":JSONObject s=m.getJSONObject("state");game.x=(float)s.getDouble("x");game.z=(float)s.getDouble("z");game.player=(float)s.getDouble("player");game.cpu=(float)s.getDouble("cpu");game.mine=s.getJSONArray("score").getInt(0);game.theirs=s.getJSONArray("score").getInt(1);game.playing=true;break;case "result":game.online=false;game.playing=false;game.winner=m.getBoolean("won")?0:1;game.mine=m.getJSONArray("score").getInt(0);game.theirs=m.getJSONArray("score").getInt(1);showProfile(m.getJSONObject("user"));status.setText(m.getBoolean("won")?"Victoria":"Derrota");break;case "error":status.setText(m.optString("error"));}}}catch(Exception e){status.setText("Mensaje no válido");}}
 private void send(String type,Float x){if(socket==null)return;try{JSONObject m=new JSONObject().put("type",type);if(x!=null)m.put("x",x);socket.send(m.toString());}catch(Exception ignored){}}
 private void ranking(){if(!configure())return;request("/api/ranking",null,null,text->{try{JSONArray rows=new JSONArray(text);StringBuilder content=new StringBuilder();for(int i=0;i<rows.length();i++){JSONObject u=rows.getJSONObject(i);content.append(i+1).append(". ").append(u.getString("name")).append(" · ").append(u.getInt("rating")).append(" Elo\n");}new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("Ranking").setMessage(content.length()==0?"Todavía no hay jugadores":content.toString()).setPositiveButton("Cerrar",null).show();}catch(Exception e){status.setText("No se pudo cargar el ranking");}});}
 private void logout(){synchronized(game){if(game.online){new androidx.appcompat.app.AlertDialog.Builder(this).setMessage("Salir concede la victoria al rival.").setPositiveButton("Salir",(d,w)->doLogout()).setNegativeButton("Cancelar",null).show();return;}}doLogout();}
 private void doLogout(){if(token==null)return;request("/api/logout",new JSONObject(),token,text->{++generation;if(socket!=null)socket.close(1000,"Logout");token=null;disconnected();profile.setText("Sesión cerrada");});}
 @Override protected void onPause(){super.onPause();surface.onPause();synchronized(game){if(!game.online)game.playing=false;}}
 @Override protected void onResume(){super.onResume();if(surface!=null)surface.onResume();}
 @Override protected void onDestroy(){++generation;ui.removeCallbacks(pulse);if(socket!=null)socket.close(1000,"Closed");http.dispatcher().cancelAll();super.onDestroy();}
}
